export const RETICLE_OVERLAY = '[data-reticle-overlay],[data-reticle-cursor],[data-reticle-hud],[data-reticle-glow],[data-reticle-mark],[data-reticle-blocker],[data-reticle-tour]';
const DEV_OVERLAYS = '[data-agentation],#__next-build-watcher,nextjs-portal,[data-nextjs-dialog],[data-nextjs-toast]';
let extraIgnore = '';
let presenterVisible = false;
export function setPresenterVisible(visible) {
    presenterVisible = visible;
}
export function isPresenterVisible() {
    return presenterVisible;
}
export function setIgnoreSelectors(selectors) {
    extraIgnore = selectors.join(',');
}
export function isReticleOverlay(el) {
    return el.closest(RETICLE_OVERLAY) !== null;
}
export function isReticleUi(node) {
    return node !== null && node.closest(RETICLE_OVERLAY) !== null;
}
export function isIgnored(el) {
    const ours = presenterVisible ? '' : RETICLE_OVERLAY;
    const sel = [ours, DEV_OVERLAYS, extraIgnore].filter((part) => part.length > 0).join(',');
    return el.closest(sel) !== null;
}
